# Try majority voting between top and bottom for each cell
print("Creating output by voting top vs bottom for each position...")

output = []
for c in range(15):
    col_values = [grid[r][c] for r in range(11)]  # All rows including divider
    counts = {}
    for v in col_values:
        counts[v] = counts.get(v, 0) + 1

    max_count = max(counts.values())
    most_common = [v for v, c in counts.items() if c == max_count]

    # If there's a clear majority (> half), use it, else keep original
    if len(most_common) == 1 and max_count > 11/2:
        output.append([most_common[0]] * 11)
    elif len(most_common) == 1:
        output.append([most_common[0]])
    else:
        # Tie or multiple modes - just take one
        output.append([most_common[0]])

print(output)

